from __future__ import annotations
import html,json
from pathlib import Path

START="<!-- EXPERIMENT_RESULTS_START -->"; END="<!-- EXPERIMENT_RESULTS_END -->"

def fmt(value):
    if value=="not_available":return "N/D"
    return f"{value:.4f}" if isinstance(value,float) else str(value)

def numeric(value,default=0.0):
    return float(value) if isinstance(value,(int,float)) else default

def table(rows,columns):
    head="".join(f"<th>{html.escape(label)}</th>" for _,label in columns)
    body="".join("<tr>"+"".join(f"<td>{html.escape(fmt(row.get(key,'N/D')))}</td>" for key,_ in columns)+"</tr>" for row in rows)
    return f'<div class="matrix"><table><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div>'

LABELS={"rag":"RAG","graph_rag":"Graph-RAG","pep_sa_rag":"PEP-SA-RAG","pep_sa_rag_v1":"PEP-SA v1","pep_sa_rag_v2":"PEP-SA v2","pep_plan_rag_v3":"PEP-Plan v3"}

def grouped_bars(rows,metrics):
    width=900; height=350; left=70; top=25; plot_h=230; group_w=250; bar_w=38
    colors={"rag":"var(--blue)","graph_rag":"var(--purple)","pep_sa_rag":"var(--green)","pep_sa_rag_v1":"var(--orange)","pep_sa_rag_v2":"var(--green)","pep_plan_rag_v3":"#d946ef"}
    parts=[f'<svg class="result-chart" viewBox="0 0 {width} {height}" role="img" aria-label="Comparación gráfica de métricas de recuperación"><line x1="{left}" y1="{top+plot_h}" x2="850" y2="{top+plot_h}" class="axis"/>']
    for tick in range(0,101,25):
        y=top+plot_h-(tick/100)*plot_h; parts.append(f'<line x1="{left}" y1="{y:.1f}" x2="850" y2="{y:.1f}" class="gridline"/><text x="58" y="{y+4:.1f}" text-anchor="end">{tick}%</text>')
    for gi,(metric,label) in enumerate(metrics):
        gx=left+gi*group_w+55
        for mi,row in enumerate(rows):
            value=row.get(metric,0); value=0 if not isinstance(value,(int,float)) else value
            h=value*plot_h; x=gx+mi*(bar_w+8); y=top+plot_h-h; method=row.get("method","")
            parts.append(f'<rect x="{x}" y="{y:.1f}" width="{bar_w}" height="{h:.1f}" rx="5" fill="{colors.get(method,"var(--orange)")}"/><text x="{x+bar_w/2}" y="{max(16,y-7):.1f}" text-anchor="middle">{value*100:.1f}%</text>')
        parts.append(f'<text x="{gx+70}" y="{top+plot_h+30}" text-anchor="middle" class="axis-label">{html.escape(label)}</text>')
    for index,method in enumerate([r.get("method") for r in rows]):
        lx=75+(index%3)*265; ly=305+(index//3)*24
        parts.append(f'<rect x="{lx}" y="{ly}" width="14" height="14" rx="3" fill="{colors.get(method,"var(--orange)")}"/><text x="{lx+20}" y="{ly+12}">{LABELS.get(method,method)}</text>')
    parts.append('</svg>'); return "".join(parts)

def horizontal_bars(rows,key,label,maximum=None):
    maximum=maximum or max(float(r.get(key,0)) for r in rows) or 1
    parts=[f'<div class="bar-chart" role="img" aria-label="{html.escape(label)}">']
    for row in rows:
        value=float(row.get(key,0)); pct=min(100,value/maximum*100); name=LABELS.get(row.get("method"),row.get("method",""))
        parts.append(f'<div class="chart-row"><span>{html.escape(name)}</span><div class="chart-track"><i style="width:{pct:.1f}%"></i></div><strong>{value:.2f}</strong></div>')
    return "".join(parts)+"</div>"

def results_fragment(summary:dict)->str:
    run=html.escape(summary.get("run_id","sin ejecución")); split=html.escape(summary.get("split","unknown"))
    retrieval=table(summary.get("retrieval_summary",[]),[("method","Método"),("n","n"),("hit_at_k","Hit@K"),("concept_recall","Concept Recall"),("prerequisite_recall","Prerequisite Recall"),("latency_ms","Latencia ms"),("nodes_visited","Nodos")])
    ablations=table(summary.get("ablation_summary",[]),[("method","Ablación"),("hit_at_k","Hit@K"),("ndcg_at_k","nDCG@K"),("prerequisite_recall","Prerequisite Recall"),("latency_ms","Latencia ms")])
    robustness=table(summary.get("robustness_summary",[]),[("method","Método"),("n","Consultas"),("hit_at_k","Hit@K"),("concept_recall","Concept Recall"),("prerequisite_recall","Prerequisite Recall")])
    rows=summary.get("retrieval_summary",[]); chart=grouped_bars(rows,[("hit_at_k","Hit@5"),("concept_recall","Concept Recall"),("prerequisite_recall","Prerequisite Recall")]) if rows else ""
    latency_chart=horizontal_bars(rows,"latency_ms","Latencia promedio de recuperación en milisegundos") if rows else ""
    best_hit=max(rows,key=lambda r:numeric(r.get("hit_at_k"),-1)) if rows else {}; best_prereq=max(rows,key=lambda r:numeric(r.get("prerequisite_recall"),-1)) if rows else {}
    rag=next((r for r in rows if r.get("method")=="rag"),{}); graph=next((r for r in rows if r.get("method")=="graph_rag"),{}); pep_v1=next((r for r in rows if r.get("method")=="pep_sa_rag_v1"),{}); pep=next((r for r in rows if r.get("method") in {"pep_sa_rag_v2","pep_sa_rag"}),{}); pep_v3=next((r for r in rows if r.get("method")=="pep_plan_rag_v3"),{})
    hit_delta=numeric(pep.get("hit_at_k"))-numeric(rag.get("hit_at_k")); prereq_delta=numeric(pep.get("prerequisite_recall"))-numeric(rag.get("prerequisite_recall"))
    v2_hit_delta=numeric(pep.get("hit_at_k"))-numeric(pep_v1.get("hit_at_k")); v2_prereq_delta=numeric(pep.get("prerequisite_recall"))-numeric(pep_v1.get("prerequisite_recall")); v2_recall_delta=numeric(pep.get("recall_at_k"))-numeric(pep_v1.get("recall_at_k")); v2_ndcg_delta=numeric(pep.get("ndcg_at_k"))-numeric(pep_v1.get("ndcg_at_k"))
    v3_hit_delta=numeric(pep_v3.get("hit_at_k"))-numeric(pep.get("hit_at_k")); v3_prereq_delta=numeric(pep_v3.get("prerequisite_recall"))-numeric(pep.get("prerequisite_recall"))
    question_count=int(summary.get("question_count",0)); retrieval_calls=question_count*len(rows); ablation_calls=question_count*len(summary.get("ablation_summary",[])); robustness_calls=sum(int(r.get("n",0)) for r in summary.get("robustness_summary",[])); total_calls=retrieval_calls+ablation_calls+robustness_calls; total_label=f"{total_calls:,}".replace(",",".")
    generation_rows=summary.get("generation_summary",[])
    generation=""
    evolution='''<section class="slide"><div class="kicker">Evolución del método · PEP-SA v1</div><h2>La primera versión activaba bien, pero seleccionaba mal</h2><div class="grid two"><article class="card green"><h3>Lo que sí funcionó</h3><p>La propagación encontró prerrequisitos y redujo la latencia histórica de 1.153 segundos a escala interactiva.</p></article><article class="card orange"><h3>Problema observado</h3><p>La activación podía dominar el score semántico y desplazar del top-5 los chunks que respondían directamente la pregunta.</p></article><article class="card blue"><h3>Evidencia del diagnóstico</h3><p>PEP-SA v1 mejoró frente a RAG en Prerequisite Recall, pero quedó detrás de Graph-RAG en Hit@5 y Concept Recall.</p></article><article class="card purple"><h3>Decisión científica</h3><p>Conservar v1, formular v2 como intervención explícita y comparar ambas sobre las mismas preguntas de validación.</p></article></div></section>
<section class="slide"><div class="kicker">Evolución del método · PEP-SA v2</div><h2>Cuatro cambios con hipótesis explícita</h2><div class="grid two"><article class="card blue"><h3>1 · Query restart</h3><p>Reinyecta las semillas en cada iteración para que la población no pierda la intención original.</p></article><article class="card purple"><h3>2 · Dirección pedagógica</h3><p>Favorece propagación hacia prerrequisitos y limita el flujo hacia sucesores.</p></article><article class="card green"><h3>3 · Reranking híbrido</h3><p>Combina relevancia directa, activación, utilidad del prerrequisito y valor instruccional.</p></article><article class="card orange"><h3>4 · Cuotas de contexto</h3><p>Reserva evidencia directa, prerrequisitos y material explicativo, adaptándose a preguntas sobre conocimiento previo.</p></article></div><div class="callout"><p>Hipótesis v2: conservar la ganancia en prerrequisitos de v1 y recuperar parte de la precisión directa de Graph-RAG.</p></div></section>
<section class="slide"><div class="kicker">Nueva propuesta · PEP-Plan-RAG v3</div><h2>De propagar conceptos a planificar evidencia para este estudiante</h2><div class="formula">U(d|q,s) = αR + βPPR + γT + δN<sub>pre</sub> + εG<sub>s</sub> + ζM + ηI + θA − λRed</div><div class="grid two"><article class="card blue"><h3>Modelo del estudiante</h3><p>Representa dominio estimado, brechas y posibles concepciones erróneas. El estado desconocido sigue siendo la condición neutral.</p></article><article class="card purple"><h3>Ruta de aprendizaje</h3><p>Recorre hacia atrás el DAG de prerrequisitos y prioriza conceptos por debajo del umbral de dominio.</p></article><article class="card green"><h3>Utilidad pedagógica</h3><p>Combina RRF, PPR, activación poblacional, necesidad del prerrequisito y valor instruccional.</p></article><article class="card orange"><h3>Optimizador de contexto</h3><p>Selecciona evidencia directa, previa e instruccional, penalizando redundancia para mantener un contexto pequeño.</p></article></div></section>'''
    comparison=f'''<section class="slide"><div class="kicker">Comparativa de versiones</div><h2>Qué cambia y cuál es el punto fuerte de cada versión</h2><div class="matrix"><table><thead><tr><th>Versión</th><th>Decisión central</th><th>Personalización</th><th>Punto fuerte</th><th>Resultado observado</th></tr></thead><tbody><tr><td>PEP-SA v1</td><td>Activación aditiva</td><td>No</td><td>Cobertura y nDCG frente a v2</td><td>Hit@5 {fmt(pep_v1.get('hit_at_k','not_available'))}</td></tr><tr><td>PEP-SA v2</td><td>Restart + dirección + cuotas</td><td>Por tipo de consulta</td><td>Prerrequisitos y latencia</td><td>Prereq {fmt(pep.get('prerequisite_recall','not_available'))}</td></tr><tr><td>PEP-Plan v3</td><td>Plan individual + utilidad + diversidad</td><td>Sí, estado explícito</td><td>Explicabilidad y contexto adaptativo</td><td>Hit@5 {fmt(pep_v3.get('hit_at_k','not_available'))}; Prereq {fmt(pep_v3.get('prerequisite_recall','not_available'))}</td></tr></tbody></table></div><div class="callout"><p>V3 no se define como ganadora por diseño: debe superar a Graph-RAG en datos. En esta ejecución cambió Hit@5 en {v3_hit_delta:+.4f} y Prerequisite Recall en {v3_prereq_delta:+.4f} frente a v2.</p></div></section>'''
    version_conclusion=f'''<section class="slide"><div class="kicker">PEP-SA v1 vs v2</div><h2>¿La modificación produjo la mejora esperada?</h2><div class="grid two"><article class="card blue"><h3>Cambio en Hit@5</h3><div class="number">{v2_hit_delta:+.4f}</div><p>PEP-SA v2 menos v1.</p></article><article class="card green"><h3>Cambio en Prerequisite Recall</h3><div class="number">{v2_prereq_delta:+.4f}</div><p>PEP-SA v2 menos v1.</p></article><article class="card orange"><h3>Cambio en Recall@5</h3><div class="number">{v2_recall_delta:+.4f}</div><p>Cobertura de todos los chunks gold.</p></article><article class="card purple"><h3>Cambio en nDCG@5</h3><div class="number">{v2_ndcg_delta:+.4f}</div><p>Calidad del orden del top-5.</p></article></div><div class="callout"><p>V2 mejoró acierto, conceptos y prerrequisitos, pero perdió cobertura y calidad de orden frente a v1. El resultado es un trade-off, no una victoria total. Conservar v1 evita reinterpretar retrospectivamente el proceso.</p></div></section>'''
    if generation_rows:
        generation_table=table(generation_rows,[("condition","Condición"),("n","n"),("token_f1","Token F1"),("concept_recall","Concept Recall"),("prerequisite_recall","Prerequisite Recall"),("latency_ms","Latencia ms"),("errors","Errores")])
        generation=f'<section class="slide"><div class="kicker">Resultados masivos · Gemini</div><h2>Generación y recuperación</h2>{generation_table}<div class="callout"><p>Las puntuaciones pedagógicas humanas se capturan en la rúbrica ciega generada con el run; no se sustituyen por afirmaciones automáticas.</p></div></section>'
    return f'''{START}
{evolution}
{comparison}
<section class="slide"><div class="kicker">Ejecución masiva · qué se hizo</div><h2>{total_calls:,} recuperaciones sin utilizar el frontend</h2><div class="grid"><article class="card blue"><div class="number">{question_count}</div><p>preguntas del split de validación</p></article><article class="card purple"><div class="number">{retrieval_calls}</div><p>consultas de la comparación principal</p></article><article class="card green"><div class="number">{ablation_calls}</div><p>consultas de ablaciones</p></article><article class="card orange"><div class="number">{robustness_calls}</div><p>consultas de robustez</p></article></div><div class="flow"><span class="node">Leer pregunta + gold</span><span class="arrow">→</span><span class="node">Ejecutar cada retriever</span><span class="arrow">→</span><span class="node">Comparar top-5</span><span class="arrow">→</span><span class="node">Guardar JSONL/CSV</span><span class="arrow">→</span><span class="node">Bootstrap 95%</span></div><div class="callout"><p>No se llamó a Gemini en este run. El objetivo fue aislar y medir la recuperación antes de evaluar la calidad de las respuestas generadas.</p></div></section>
<section class="slide"><div class="kicker">Cómo leer las métricas</div><h2>¿Qué mide cada número?</h2><div class="grid"><article class="card"><h3>Hit@5</h3><p>Vale 1 si al menos un chunk correcto aparece entre los cinco primeros. Responde: “¿encontró alguna evidencia útil?”</p></article><article class="card"><h3>Recall@5</h3><p>Proporción de todos los chunks gold que aparecen en el top-5. Premia recuperar evidencia completa.</p></article><article class="card"><h3>MRR</h3><p>Premia que el primer chunk correcto aparezca pronto. Un acierto en posición 1 vale más que en posición 5.</p></article><article class="card"><h3>nDCG@5</h3><p>Mide calidad del orden completo, dando más importancia a evidencia relevante ubicada arriba.</p></article><article class="card"><h3>Concept Recall</h3><p>Cuántos conceptos requeridos fueron identificados por la evidencia recuperada.</p></article><article class="card"><h3>Prerequisite Recall</h3><p>Cuántos conocimientos previos gold fueron recuperados o activados por el método.</p></article></div><div class="callout"><p>Ejemplo: si hay dos chunks gold y el sistema recupera uno en el top-5, Hit@5 = 1 y Recall@5 = 0,5.</p></div></section>
<section class="slide"><div class="kicker">Ejemplo observado · radicales</div><h2>Una pregunta, tres comportamientos</h2><p class="lead">“¿Qué conocimientos previos se necesitan para comprender radicales?”</p><div class="grid"><article class="card blue"><h3>RAG</h3><p>No recuperó ninguno de los chunks gold en el top-5. Sus resultados se desviaron hacia verificación de conceptos, polinomios y trigonometría.</p><p><strong>Hit@5: 0</strong></p></article><article class="card purple"><h3>Graph-RAG</h3><p>Recuperó el chunk <code>p0046_chunk00</code> asociado a radicales y activó notación científica, el prerrequisito gold.</p><p><strong>Hit@5: 1</strong></p></article><article class="card green"><h3>PEP-SA-RAG</h3><p>Activó conceptos cercanos a exponentes y radicales, pero los chunks finales se desplazaron hacia modelado y polinomios.</p><p><strong>Hit@5: 0</strong></p></article></div><div class="callout"><p>Este caso muestra la diferencia entre <strong>activar un concepto pertinente</strong> y lograr que sus chunks permanezcan en el contexto final. Es una pista concreta para mejorar el reranking de PEP-SA-RAG.</p></div></section>
<section class="slide"><div class="kicker">Resultados masivos · {run}</div><h2>Comparación observada de recuperación</h2>{retrieval}<div class="callout"><p>Split: <strong>{split}</strong>. Valores cargados desde artefactos de ejecución, no simulados. La comparación permite que cada método gane o pierda según la métrica.</p></div></section>
<section class="slide"><div class="kicker">Resultados masivos · gráfica</div><h2>Exactitud conceptual y de prerrequisitos</h2>{chart}<div class="callout"><p>La gráfica compara las cinco condiciones con los mismos datos y top-5. La tabla anterior permite verificar qué método lidera cada métrica sin atribuir mejoras no observadas.</p></div></section>
<section class="slide"><div class="kicker">Costo computacional</div><h2>Más estructura, poca latencia adicional</h2>{latency_chart}<div class="callout"><p>RAG: {fmt(rag.get('latency_ms','not_available'))} ms. PEP-SA-RAG añadió aproximadamente {fmt(float(pep.get('latency_ms',0))-float(rag.get('latency_ms',0)))} ms y visitó {fmt(pep.get('nodes_visited','not_available'))} nodos en promedio. Ya no recorre los 448 conceptos completos.</p></div></section>
<section class="slide"><div class="kicker">Resultados masivos · ablaciones</div><h2>¿Qué componente produce cada efecto?</h2>{ablations}<div class="callout"><p>Las ablaciones separan dense, BM25, RRF, expansión, PPR, ponderación uniforme y PEP-SA completo. Se ajustan sobre validación, nunca sobre test.</p></div></section>
<section class="slide"><div class="kicker">Resultados masivos · robustez</div><h2>Estabilidad ante reformulaciones</h2>{robustness}<div class="callout"><p>Cada pregunta se ejecutó en versión original, cortés e informal. El detalle por variante está disponible en JSONL y CSV.</p></div></section>
<section class="slide"><div class="kicker">Conclusión de esta ejecución</div><h2>La hipótesis aún no queda demostrada</h2><div class="grid two"><article class="card purple"><h3>Resultado más fuerte</h3><p>{html.escape(LABELS.get(best_hit.get('method',''),best_hit.get('method','')))} obtuvo el mayor Hit@5 ({fmt(best_hit.get('hit_at_k','not_available'))}) y {html.escape(LABELS.get(best_prereq.get('method',''),best_prereq.get('method','')))} el mayor Prerequisite Recall ({fmt(best_prereq.get('prerequisite_recall','not_available'))}).</p></article><article class="card green"><h3>Aporte observado de PEP-SA</h3><p>Frente a RAG, cambió Hit@5 en {hit_delta:+.4f} y Prerequisite Recall en {prereq_delta:+.4f}.</p></article><article class="card orange"><h3>Problema identificado</h3><p>La activación puede encontrar conceptos pedagógicos relevantes sin conservar sus chunks en el top-5 final.</p></article><article class="card blue"><h3>Siguiente contraste</h3><p>Mejorar y ablacionar el reranking sobre validación; después congelar parámetros y ejecutar una sola vez sobre test.</p></article></div><div class="callout"><p>Conclusión limitada: PEP-SA-RAG mejora frente al baseline RAG en esta validación, pero Graph-RAG con PPR sigue siendo superior. No se afirma todavía mejora pedagógica porque falta la evaluación Gemini y la rúbrica humana ciega.</p></div></section>
{version_conclusion}
{generation}
{END}'''

def update_presentation(presentation:Path,summary:dict):
    text=presentation.read_text(encoding="utf-8"); fragment=results_fragment(summary)
    if START in text and END in text:
        before=text.split(START,1)[0]; after=text.split(END,1)[1]; text=before+fragment+after
    else:
        marker='<section class="slide"><div class="kicker">Plan de ejecución</div>'
        text=text.replace(marker,fragment+'\n\n'+marker)
    presentation.write_text(text,encoding="utf-8")
